From 81ea328641b310bad0415f34934f96bd16f54be3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:30:16 +0100
Subject: [PATCH] applets/brightness: show an error instead of disappearing
 without powerdevil

The tray only loaded Brightness & Color while powerdevil was running, so
it vanished when the service was gone, taking Night Light and the theme
switch with it. Keep it loaded and say why brightness is unavailable.

BUG: 494514
---
 applets/brightness/PopupDialog.qml                    | 7 +++++++
 applets/brightness/metadata.json                      | 1 -
 applets/brightness/plugin/screenbrightnesscontrol.cpp | 5 +++++
 applets/brightness/plugin/screenbrightnesscontrol.h   | 5 ++++-
 4 files changed, 16 insertions(+), 2 deletions(-)

diff --git a/applets/brightness/PopupDialog.qml b/applets/brightness/PopupDialog.qml
index 435e75ae4..74d92fab5 100644
--- a/applets/brightness/PopupDialog.qml
+++ b/applets/brightness/PopupDialog.qml
@@ -52,6 +52,13 @@ PlasmaExtras.Representation {
             width: scrollView.contentItem.width
             spacing: Kirigami.Units.smallSpacing * 2

+            Kirigami.InlineMessage {
+                Layout.fillWidth: true
+                type: Kirigami.MessageType.Error
+                text: i18n("Brightness can't be adjusted because the Power Management service isn't running.")
+                visible: !dialog.screenBrightnessControl.isServiceAvailable
+            }
+
             Repeater {
                 id: screenBrightnessRepeater
                 model: dialog.screenBrightnessControl.displays
diff --git a/applets/brightness/metadata.json b/applets/brightness/metadata.json
index 0c1adc906..1165059ae 100644
--- a/applets/brightness/metadata.json
+++ b/applets/brightness/metadata.json
@@ -269,7 +269,6 @@
     },
     "Keywords": "Power Management;Brightness;Color;Light;Screen;Display;Monitor;Keyboard;Night;Temperature",
     "X-Plasma-API-Minimum-Version": "6.0",
-    "X-Plasma-DBusActivationService": "org.kde.Solid.PowerManagement",
     "X-Plasma-NotificationAreaCategory": "Hardware",
     "X-Plasma-Provides": [
         "org.kde.plasma.brightness"
diff --git a/applets/brightness/plugin/screenbrightnesscontrol.cpp b/applets/brightness/plugin/screenbrightnesscontrol.cpp
index c145b6f3a..22ceb8419 100644
--- a/applets/brightness/plugin/screenbrightnesscontrol.cpp
+++ b/applets/brightness/plugin/screenbrightnesscontrol.cpp
@@ -309,4 +309,9 @@ QBindable<bool> ScreenBrightnessControl::bindableIsBrightnessAvailable()
     return &m_isBrightnessAvailable;
 }

+QBindable<bool> ScreenBrightnessControl::bindableIsServiceAvailable()
+{
+    return &m_serviceRegistered;
+}
+
 #include "moc_screenbrightnesscontrol.cpp"
diff --git a/applets/brightness/plugin/screenbrightnesscontrol.h b/applets/brightness/plugin/screenbrightnesscontrol.h
index 036b6ac32..6dcee28cb 100644
--- a/applets/brightness/plugin/screenbrightnesscontrol.h
+++ b/applets/brightness/plugin/screenbrightnesscontrol.h
@@ -27,6 +27,7 @@ class ScreenBrightnessControl : public QObject
     Q_PROPERTY(QAbstractListModel *displays READ displays CONSTANT)

     Q_PROPERTY(bool isBrightnessAvailable READ default NOTIFY isBrightnessAvailableChanged BINDABLE bindableIsBrightnessAvailable)
+    Q_PROPERTY(bool isServiceAvailable READ default NOTIFY isServiceAvailableChanged BINDABLE bindableIsServiceAvailable)
     Q_PROPERTY(bool isSilent MEMBER m_isSilent)

 public:
@@ -45,6 +46,7 @@ public:
     const ScreenBrightnessDisplayModel *displays() const;

     QBindable<bool> bindableIsBrightnessAvailable();
+    QBindable<bool> bindableIsServiceAvailable();

     /**
      * Adjust brightness up or down for a predetermined set of displays by a given ratio.
@@ -65,6 +67,7 @@ public Q_SLOTS:

 Q_SIGNALS:
     void isBrightnessAvailableChanged(bool status);
+    void isServiceAvailableChanged(bool status);

 private Q_SLOTS:
     void onGlobalPropertiesChanged(const QString &ifaceName, const QVariantMap &changedProps, const QStringList &invalidatedProps);
@@ -78,6 +81,7 @@ private:
     QCoro::Task<void> queryAndInsertDisplayData(const QString &displayNames);

     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(ScreenBrightnessControl, bool, m_isBrightnessAvailable, false, &ScreenBrightnessControl::isBrightnessAvailableChanged);
+    Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(ScreenBrightnessControl, bool, m_serviceRegistered, false, &ScreenBrightnessControl::isServiceAvailableChanged);

     ScreenBrightnessDisplayModel m_displays;
     QString m_alreadyChangedContext;
@@ -87,5 +91,4 @@ private:
     bool m_isSilent = false;
     bool m_displaysUpdating = false;
     bool m_shouldRecheckDisplays = false;
-    bool m_serviceRegistered = false;
 };
-- 
